    /// <summary>Gets the address that is handed to native code.</summary>
    internal static nint Pointer => (nint)(delegate* unmanaged[Cdecl]<nint, byte*, nint, void>)&Invoke;

    [UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    private static void Invoke(nint list, byte* tag, nint userData)
    {
        try
        {
            if (Gst.Interop.CallbackHandle.GetState<Gst.TagForeachFunc>(userData) is not { } callback)
            {
                return;
            }

            Gst.TagList listValue = Gst.TagList.FromNative(list, Gst.Interop.Transfer.None)
                ?? throw new InvalidOperationException("GstTagForeachFunc passed no list.");
            string tagValue = Gst.Interop.GMarshal.PtrToStringUtf8((nint)tag)
                ?? throw new InvalidOperationException("GstTagForeachFunc passed no tag.");
            callback(listValue, tagValue);
        }
        catch (Exception exception)
        {
            Gst.Interop.ExceptionTrap.Report(exception);
        }
    }
}

/// <summary>
/// A function that will repeatedly be called in the thread created by
/// a #GstTask.
/// </summary>
public delegate void TaskFunction();

/// <summary>The native entry point of <see cref="Gst.TaskFunction"/>.</summary>
internal static unsafe class TaskFunctionTrampoline
{
    /// <summary>Gets the address that is handed to native code.</summary>
    internal static nint Pointer => (nint)(delegate* unmanaged[Cdecl]<nint, void>)&Invoke;

    [UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    private static void Invoke(nint userData)
    {
        try
        {
            if (Gst.Interop.CallbackHandle.GetState<Gst.TaskFunction>(userData) is not { } callback)
            {
                return;
            }

            callback();
        }
        catch (Exception exception)
        {
            Gst.Interop.ExceptionTrap.Report(exception);
        }
    }
}

/// <summary>A function that will be called by typefinding.</summary>
/// <param name="find">A #GstTypeFind structure</param>
public delegate void TypeFindFunction(Gst.TypeFind find);

/// <summary>The native entry point of <see cref="Gst.TypeFindFunction"/>.</summary>
internal static unsafe class TypeFindFunctionTrampoline
{
    /// <summary>Gets the address that is handed to native code.</summary>
    internal static nint Pointer => (nint)(delegate* unmanaged[Cdecl]<nint, nint, void>)&Invoke;

    [UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    private static void Invoke(nint find, nint userData)
    {
        try
        {
            if (Gst.Interop.CallbackHandle.GetState<Gst.TypeFindFunction>(userData) is not { } callback)
            {
                return;
            }

            Gst.TypeFind findValue = Gst.TypeFind.FromNative(find)
                ?? throw new InvalidOperationException("GstTypeFindFunction passed no find.");
            callback(findValue);
        }
        catch (Exception exception)
        {
            Gst.Interop.ExceptionTrap.Report(exception);
        }
    }
}
